// A number from low to high (in either order), as <random> draws one.
float randomBetween(float low, float high)
{
	static std::mt19937 generator{std::random_device{}()};
	std::uniform_real_distribution<float> number(std::min(low, high), std::max(low, high));
	return number(generator);
}

// -1, 0 or 1, as exprtk's sgn().
float sign(float value)
{
	return value < 0.0f ? -1.0f : (value > 0.0f ? 1.0f : 0.0f);
}

// The frames a timer waits for `seconds`, as the engine counts them: at least one.
int framesFor(float seconds)
{
	return std::max(1, static_cast<int>(std::lround(seconds * static_cast<float>(framerate))));
}

// A picture the engine drew, pixel for pixel, as an SFML image.
sf::Image imageOf(const xge::Bitmap& picture)
{
	return sf::Image({static_cast<unsigned int>(picture.width), static_cast<unsigned int>(picture.height)}, picture.rgba.data());
}

// A note's pitch (A4, C#5, Eb3) in hertz, as the engine reads it.
float hertz(const std::string& note)
{
	return xge::pitchFromName(note).value_or(0.0f);
}
